<script setup>
import {ref,computed,onMounted} from 'vue'
const props=defineProps({request:Function,context:Object})
const allowed=computed(()=>!props.context.portal&&props.context.roles.includes('superAdmin'))
const key='SNOWY_SYS_DEFAULT_CAPTCHA_OPEN_FLAG_FOR_C',enabled=ref(true),saved=ref(null),busy=ref(false),error=ref(''),notice=ref('')
async function read(){const list=await props.request('/dev/config/sysBaseList'),setting=list.find(x=>x.configKey===key);if(!setting||!['true','false'].includes(String(setting.configValue)))throw Error('无法读取供应商门户验证码配置，请刷新重试');saved.value=String(setting.configValue)==='true';enabled.value=saved.value}
async function load(){busy.value=true;error.value='';notice.value='';try{await read()}catch(e){error.value=e.message}finally{busy.value=false}}
async function save(){if(!allowed.value||busy.value||saved.value===null)return;busy.value=true;error.value='';notice.value='';const next=enabled.value;try{await props.request('/dev/config/editBatch',[{configKey:key,configValue:String(next)}],'POST');await read();if(saved.value!==next)throw Error('设置未生效，请刷新后重试');notice.value=next?'已开启供应商门户图片验证码。刷新门户登录页后生效。':'已关闭供应商门户图片验证码。刷新门户登录页后，可直接用账号和密码登录。'}catch(e){error.value=e.message}finally{busy.value=false}}
onMounted(()=>{if(allowed.value)load()})
</script>
<template><section class="portal-login-settings" :aria-busy="busy"><template v-if="allowed"><div class="panel-heading"><div><h2>供应商门户登录设置</h2><p>设置供应商使用账号、密码登录时是否需要填写图片验证码。</p></div><button class="btn" :disabled="busy" @click="load">刷新设置</button></div><p v-if="error" role="alert" class="form-error">{{error}}</p><p v-if="notice" role="status" class="info-note">{{notice}}</p><form @submit.prevent="save"><label class="captcha-setting"><input aria-label="供应商门户图片验证码" role="switch" type="checkbox" v-model="enabled" :disabled="busy||saved===null"/><span><strong>供应商门户图片验证码</strong><small>{{enabled?'开启：登录时填写图片验证码':'关闭：登录时无需图片验证码'}}</small></span></label><p class="muted">当前已保存：{{saved===null?'正在读取…':saved?'开启':'关闭'}}。调整后刷新供应商门户登录页生效。</p><button class="btn primary" :disabled="busy||saved===null||enabled===saved">保存门户登录设置</button></form></template><p v-else class="info-note">仅内部系统管理员可管理门户登录设置。</p></section></template>
<style scoped>.portal-login-settings{padding:24px}.captcha-setting{display:flex;align-items:center;gap:14px;padding:20px;border:1px solid #dce5e0;border-radius:10px;max-width:640px;margin:20px 0}.captcha-setting input{width:22px;height:22px;accent-color:#28664d}.captcha-setting strong,.captcha-setting small{display:block}.captcha-setting small{margin-top:7px;color:#68786e}.portal-login-settings .muted{margin:18px 0}</style>
